import{_ as o,a0 as n,w as p,s as d,I as e,x as t,a1 as a,A as l,ao as g}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const G=JSON.parse('{"title":"在 Git 中怎樣克隆、修改、添加和刪除文件？ | LCTT x X-CMD","titleTemplate":false,"description":"在 Git 中怎樣克隆、修改、添加和刪除文件？ | LCTT (201804) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"在 Git 中怎樣克隆、修改、添加和刪除文件？ | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"在 Git 中怎樣克隆、修改、添加和刪除文件？ | LCTT (201804) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201804/20180213 How to clone, modify, add, and delete files in Git","title":"在 Git 中怎樣克隆、修改、添加和刪除文件？","tag":"201804","desc":""},"relativePath":"201804/20180213 How to clone, modify, add, and delete files in Git.md","filePath":"[post].md"}'),r={name:"201804/20180213 How to clone, modify, add, and delete files in Git.md"};function u(c,i,h,b,m,k){const s=n("Link");return p(),d("div",null,[i[27]||(i[27]=e("h1",{id:"在-git-中怎樣克隆、修改、添加和刪除文件",tabindex:"-1"},[t("在 Git 中怎樣克隆、修改、添加和刪除文件？ "),e("a",{class:"header-anchor",href:"#在-git-中怎樣克隆、修改、添加和刪除文件","aria-label":"Permalink to “在 Git 中怎樣克隆、修改、添加和刪除文件？”"},"​")],-1)),i[28]||(i[28]=e("p",null,[e("img",{src:"https://opensource.com/sites/default/files/styles/image-full-size/public/lead-images/LIFE_cat.png?itok=ta54QTAf",alt:""})],-1)),e("p",null,[i[1]||(i[1]=t("在 ",-1)),a(s,{href:"https://linux.cn/article-9319-1.html"},{default:l(()=>[...i[0]||(i[0]=[t("本系列的第一篇文章",-1)])]),_:1}),i[2]||(i[2]=t(" 開始使用 Git 時，我們創建了一個簡單的 Git 倉庫，並用我們的計算機連接到它，向其中添加一個文件。在本文中，我們將學習一些關於 Git 的其他內容，即如何克隆（下載）、修改、添加和刪除 Git 倉庫中的文件。",-1))]),i[29]||(i[29]=e("h3",{id:"讓我們來克隆一下",tabindex:"-1"},[t("讓我們來克隆一下 "),e("a",{class:"header-anchor",href:"#讓我們來克隆一下","aria-label":"Permalink to “讓我們來克隆一下”"},"​")],-1)),i[30]||(i[30]=e("p",null,[t("假設你在 GitHub 上已經有一個 Git 倉庫，並且想從它那裏獲取你的文件——也許你在你的計算機上丟失了本地副本，或者你正在另一台計算機上工作，但是想訪問倉庫中的文件，你該怎麼辦？從 GitHub 下載你的文件？沒錯！在 Git 術語中我們稱之為“"),e("ruby",null,[t("克隆"),e("rt",null,"clone")]),t("”。（你也可以將倉庫作為 ZIP 文件下載，但我們將在本文中探討克隆方式。）")],-1)),e("p",null,[i[4]||(i[4]=t("讓我們克隆在上一篇文章中創建的名為 Demo 的倉庫。（如果你還沒有創建 Demo 倉庫，請跳回到",-1)),a(s,{href:"https://linux.cn/article-9319-1.html"},{default:l(()=>[...i[3]||(i[3]=[t("那篇文章",-1)])]),_:1}),i[5]||(i[5]=t("並在繼續之前執行那些步驟）要克隆文件，只需打開瀏覽器並導航到 ",-1)),i[6]||(i[6]=e("code",null,"https://github.com/<your_username>/Demo",-1)),i[7]||(i[7]=t(" (其中 ",-1)),i[8]||(i[8]=e("code",null,"<your_username>",-1)),i[9]||(i[9]=t(" 是你倉庫的名稱。例如，我的倉庫是 ",-1)),i[10]||(i[10]=e("code",null,"https://github.com/kedark3/Demo",-1)),i[11]||(i[11]=t(")。一旦你導航到該 URL，點擊“",-1)),i[12]||(i[12]=e("ruby",null,[t("克隆或下載"),e("rt",null,"Clone or download")],-1)),i[13]||(i[13]=t("”按鈕，你的瀏覽器看起來應該是這樣的：",-1))]),i[31]||(i[31]=g(`<p><img src="https://opensource.com/sites/default/files/styles/panopoly_image_original/public/u128651/git_guide11.png?itok=wJYqZyBX" alt=""></p><p>正如你在上面看到的，“<ruby>使用 HTTPS 克隆<rt>Clone with HTTPS</rt></ruby>”選項已打開。從該下拉框中複製你的倉庫地址（<code>https://github.com/&lt;your_username&gt;/Demo.git</code>），打開終端並輸入以下命令將 GitHub 倉庫克隆到你的計算機：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>git clone https://github.com/&lt;your_username&gt;/Demo.git</span></span></code></pre></div><p>然後，要查看 <code>Demo</code> 目錄中的文件列表，請輸入以下命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>ls Demo/</span></span></code></pre></div><p>終端看起來應該是這樣的：</p><p><img src="https://opensource.com/sites/default/files/styles/panopoly_image_original/public/u128651/git_guide12.png?itok=E7ZG9t-8" alt=""></p><h3 id="修改文件" tabindex="-1">修改文件 <a class="header-anchor" href="#修改文件" aria-label="Permalink to “修改文件”">​</a></h3><p>現在我們已經克隆了倉庫，讓我們修改文件並在 GitHub 上更新它們。首先，逐個輸入下面的命令，將目錄更改為 <code>Demo/</code>，檢查 <code>README.md</code> 中的內容，添加新的（附加的）內容到 <code>README.md</code>，然後使用 <code>git status</code> 檢查狀態:</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>cd Demo/</span></span>
<span class="line"><span>ls</span></span>
<span class="line"><span>cat README.md</span></span>
<span class="line"><span>echo &quot;Added another line to REAMD.md&quot; &gt;&gt; README.md</span></span>
<span class="line"><span>cat README.md</span></span>
<span class="line"><span>git status</span></span></code></pre></div><p>如果你逐一運行這些命令，終端看起開將會是這樣：</p><p><img src="https://opensource.com/sites/default/files/styles/panopoly_image_original/public/u128651/git_guide12.5.png?itok=jhb-EPH1" alt=""></p><p>讓我們看一下 <code>git status</code> 的輸出，並瞭解它的意思。不要擔心這樣的語句：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>On branch master</span></span>
<span class="line"><span>Your branch is up-to-date with &#39;origin/master&#39;.&quot;.</span></span></code></pre></div><p>因為我們還沒有學習這些。（LCTT 譯註：學了你就知道了）下一行説：<code>Changes not staged for commit</code>（變化未籌劃提交）；這是告訴你，它下面列出的文件沒有被標記準備（“<ruby>籌劃<rt>stage</rt></ruby>”）提交。如果你運行 <code>git add</code>，Git 會把這些文件標記為 <code>Ready for commit</code>（準備提交）；換句話説就是 <code>Changes staged for commit</code>（變化籌劃提交）。在我們這樣做之前，讓我們用 <code>git diff</code> 命令來檢查我們添加了什麼到 Git 中，然後運行 <code>git add</code>。</p><p>這裏是終端輸出：</p><p><img src="https://opensource.com/sites/default/files/styles/panopoly_image_original/public/u128651/git_guide13.png?itok=983p_vNw" alt=""></p><p>我們來分析一下：</p><ul><li><code>diff --git a/README.md b/README.md</code> 是 Git 比較的內容（在這個例子中是 <code>README.md</code>）。</li><li><code>--- a/README.md</code> 會顯示從文件中刪除的任何東西。</li><li><code>+++ b/README.md</code> 會顯示從文件中添加的任何東西。</li><li>任何添加到文件中的內容都以綠色文本打印，並在該行的開頭加上 <code>+</code> 號。</li><li>如果我們刪除了任何內容，它將以紅色文本打印，並在該行的開頭加上 <code>-</code> 號。</li><li>現在 <code>git status</code> 顯示 <code>Changes to be committed:</code>（變化將被提交），並列出文件名（即 <code>README.md</code>）以及該文件發生了什麼（即它已經被 <code>modified</code> 並準備提交）。</li></ul><p>提示：如果你已經運行了 <code>git add</code>，現在你想看看文件有什麼不同，通常 <code>git diff</code> 不會輸出任何東西，因為你已經添加了文件。相反，你必須使用 <code>git diff --cached</code>。它會告訴你 Git 添加的當前版本和以前版本文件之間的差別。你的終端輸出看起來會是這樣：</p><p><img src="https://opensource.com/sites/default/files/styles/panopoly_image_original/public/u128651/git_guide14.png?itok=bva9fHJj" alt=""></p><h3 id="上傳文件到你的倉庫" tabindex="-1">上傳文件到你的倉庫 <a class="header-anchor" href="#上傳文件到你的倉庫" aria-label="Permalink to “上傳文件到你的倉庫”">​</a></h3><p>我們用一些新內容修改了 <code>README.md</code> 文件，現在是時候將它上傳到 GitHub。</p><p>讓我們提交更改並將其推送到 GitHub。運行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>git commit -m &quot;Updated Readme file&quot;</span></span></code></pre></div><p>這告訴 Git 你正在“提交”已經“添加”的更改，你可能還記得，從本系列的第一部分中，添加一條消息來解釋你在提交中所做的操作是非常重要的，以便你在稍後回顧 Git 日誌時瞭解當時的目的。（我們將在下一篇文章中更多地關注這個話題。）<code>Updated Readme file</code> 是這個提交的消息——如果你認為這沒有合理解釋你所做的事情，那麼請根據需要寫下你的提交消息。</p><p>運行 <code>git push -u origin master</code>，這會提示你輸入用户名和密碼，然後將文件上傳到你的 GitHub 倉庫。刷新你的 GitHub 頁面，你應該會看到剛剛對 <code>README.md</code> 所做的更改。</p><p><img src="https://opensource.com/sites/default/files/styles/panopoly_image_original/public/u128651/git_guide15.png?itok=Qa3spy13" alt=""></p><p>終端的右下角顯示我提交了更改，檢查了 Git 狀態，並將更改推送到了 GitHub。<code>git status</code> 顯示：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Your branch is ahead of &#39;origin/master&#39; by 1 commit</span></span>
<span class="line"><span>  (use &quot;git push&quot; to publish your local commits)</span></span></code></pre></div><p>第一行表示在本地倉庫中有一個提交，但不在 <code>origin/master</code> 中（即在 GitHub 上）。下一行指示我們將這些更改推送到 <code>origin/master</code> 中，這就是我們所做的。（在本例中，請參閲本系列的第一篇文章，以喚醒你對 <code>origin</code> 含義的記憶。我將在下一篇文章中討論分支的時候，解釋 <code>master</code> 的含義。）</p><h3 id="添加新文件到-git" tabindex="-1">添加新文件到 Git <a class="header-anchor" href="#添加新文件到-git" aria-label="Permalink to “添加新文件到 Git”">​</a></h3><p>現在我們修改了一個文件並在 GitHub 上更新了它，讓我們創建一個新文件，將它添加到 Git，然後將其上傳到 GitHub。 運行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>echo &quot;This is a new file&quot; &gt;&gt; file.txt</span></span></code></pre></div><p>這將會創建一個名為 <code>file.txt</code> 的新文件。</p><p>如果使用 <code>cat</code> 查看它：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>cat file.txt</span></span></code></pre></div><p>你將看到文件的內容。現在繼續運行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>git status</span></span></code></pre></div><p>Git 報告説你的倉庫中有一個未跟蹤的文件（名為 <code>file.txt</code>）。這是 Git 告訴你説在你的計算機中的倉庫目錄下有一個新文件，然而你並沒有告訴 Git，Git 也沒有跟蹤你所做的任何修改。</p><p><img src="https://opensource.com/sites/default/files/styles/panopoly_image_original/public/u128651/git_guide16.png?itok=UZpSKL13" alt=""></p><p>我們需要告訴 Git 跟蹤這個文件，以便我們可以提交併上傳文件到我們的倉庫。以下是執行該操作的命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>git add file.txt</span></span>
<span class="line"><span>git status</span></span></code></pre></div><p>終端輸出如下：</p><p><img src="https://opensource.com/sites/default/files/styles/panopoly_image_original/public/u128651/git_guide17.png?itok=quV-75Na" alt=""></p><p><code>git status</code> 告訴你有 <code>file.txt</code> 被修改，對於 Git 來説它是一個 <code>new file</code>，Git 在此之前並不知道。現在我們已經為 Git 添加了 <code>file.txt</code>，我們可以提交更改並將其推送到 <code>origin/master</code>。</p><p><img src="https://opensource.com/sites/default/files/styles/panopoly_image_original/public/u128651/git_guide18.png?itok=e0D7-eol" alt=""></p><p>Git 現在已經將這個新文件上傳到 GitHub；如果刷新 GitHub 頁面，則應該在 GitHub 上的倉庫中看到新文件 <code>file.txt</code>。</p><p><img src="https://opensource.com/sites/default/files/styles/panopoly_image_original/public/u128651/git_guide19.png?itok=FcuSsHQ6" alt=""></p><p>通過這些步驟，你可以創建儘可能多的文件，將它們添加到 Git 中，然後提交併將它們推送到 GitHub。</p><h3 id="從-git-中刪除文件" tabindex="-1">從 Git 中刪除文件 <a class="header-anchor" href="#從-git-中刪除文件" aria-label="Permalink to “從 Git 中刪除文件”">​</a></h3><p>如果我們發現我們犯了一個錯誤，並且需要從我們的倉庫中刪除 <code>file.txt</code>，該怎麼辦？一種方法是使用以下命令從本地副本中刪除文件：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>rm file.txt</span></span></code></pre></div><p>如果你現在做 <code>git status</code>，Git 就會説有一個文件 <code>not staged for commit</code>（未籌劃提交），並且它已經從倉庫的本地拷貝中刪除了。如果我們現在運行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>git add file.txt</span></span>
<span class="line"><span>git status</span></span></code></pre></div><p>我知道我們正在刪除這個文件，但是我們仍然運行 <code>git add</code>，因為我們需要告訴 Git 我們正在做的<strong>更改</strong>，<code>git add</code> 可以用於我們添加新文件、修改一個已存在文件的內容、或者從倉庫中刪除文件時。實際上，<code>git add</code> 將所有更改考慮在內，並將這些籌劃提交這些更改。如果有疑問，請仔細查看下面終端屏幕截圖中每個命令的輸出。</p><p>Git 會告訴我們已刪除的文件正在進行提交。只要你提交此更改並將其推送到 GitHub，該文件也將從 GitHub 的倉庫中刪除。運行以下命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>git commit -m &quot;Delete file.txt&quot;</span></span>
<span class="line"><span>git push -u origin master</span></span></code></pre></div><p>現在你的終端看起來像這樣：</p><p><img src="https://opensource.com/sites/default/files/styles/panopoly_image_original/public/u128651/git_guide20.png?itok=SrJMqNXC" alt=""></p><p>你的 GitHub 看起來像這樣：</p><p><img src="https://opensource.com/sites/default/files/styles/panopoly_image_original/public/u128651/git_guide21.png?itok=RhXM4Gua" alt=""></p><p>現在你知道如何從你的倉庫克隆、添加、修改和刪除 Git 文件。本系列的下一篇文章將檢查 Git 分支。</p><hr>`,64)),e("p",null,[i[15]||(i[15]=t("via: ",-1)),a(s,{href:"https://opensource.com/article/18/2/how-clone-modify-add-delete-git-files"},{default:l(()=>[...i[14]||(i[14]=[t("https://opensource.com/article/18/2/how-clone-modify-add-delete-git-files",-1)])]),_:1})]),e("p",null,[i[19]||(i[19]=t("作者：",-1)),a(s,{href:"https://opensource.com/users/kkulkarn"},{default:l(()=>[...i[16]||(i[16]=[t("Kedar Vijay Kulkarni",-1)])]),_:1}),i[20]||(i[20]=t(" 譯者：",-1)),a(s,{href:"https://github.com/MjSeven"},{default:l(()=>[...i[17]||(i[17]=[t("MjSeven",-1)])]),_:1}),i[21]||(i[21]=t(" 校對：",-1)),a(s,{href:"https://github.com/wxy"},{default:l(()=>[...i[18]||(i[18]=[t("wxy",-1)])]),_:1})]),e("p",null,[i[24]||(i[24]=t("本文由 ",-1)),a(s,{href:"https://github.com/LCTT/TranslateProject"},{default:l(()=>[...i[22]||(i[22]=[t("LCTT",-1)])]),_:1}),i[25]||(i[25]=t(" 原創編譯，",-1)),a(s,{href:"https://linux.cn/"},{default:l(()=>[...i[23]||(i[23]=[t("Linux中國",-1)])]),_:1}),i[26]||(i[26]=t(" 榮譽推出",-1))])])}const C=o(r,[["render",u]]);export{G as __pageData,C as default};
